-- Defense in depth for case relationships. API checks remain mandatory.
CREATE TRIGGER analysis_tasks_case_insert BEFORE INSERT ON analysis_tasks WHEN NOT EXISTS(SELECT 1 FROM family_services f WHERE f.id=NEW.family_service_id AND f.family_id=NEW.family_id AND f.service_id=NEW.service_id) BEGIN SELECT RAISE(ABORT,'CASE_MISMATCH'); END;
CREATE TRIGGER analysis_tasks_case_update BEFORE UPDATE ON analysis_tasks WHEN NOT EXISTS(SELECT 1 FROM family_services f WHERE f.id=NEW.family_service_id AND f.family_id=NEW.family_id AND f.service_id=NEW.service_id) BEGIN SELECT RAISE(ABORT,'CASE_MISMATCH'); END;
CREATE TRIGGER execution_tasks_case_insert BEFORE INSERT ON execution_tasks WHEN NOT EXISTS(SELECT 1 FROM family_services f WHERE f.id=NEW.family_service_id AND f.family_id=NEW.family_id AND f.service_id=NEW.service_id) BEGIN SELECT RAISE(ABORT,'CASE_MISMATCH'); END;
CREATE TRIGGER execution_tasks_case_update BEFORE UPDATE ON execution_tasks WHEN NOT EXISTS(SELECT 1 FROM family_services f WHERE f.id=NEW.family_service_id AND f.family_id=NEW.family_id AND f.service_id=NEW.service_id) BEGIN SELECT RAISE(ABORT,'CASE_MISMATCH'); END;
CREATE TRIGGER task_documents_case_insert BEFORE INSERT ON task_documents WHEN NOT EXISTS(SELECT 1 FROM documents d LEFT JOIN analysis_tasks a ON a.id=NEW.analysis_task_id LEFT JOIN execution_tasks e ON e.id=NEW.execution_task_id WHERE d.id=NEW.document_id AND (a.family_id=d.family_id OR e.family_id=d.family_id)) BEGIN SELECT RAISE(ABORT,'CASE_MISMATCH'); END;
CREATE TRIGGER meeting_items_case_insert BEFORE INSERT ON meeting_items WHEN NOT EXISTS(SELECT 1 FROM meetings m WHERE m.id=NEW.meeting_id AND m.family_id=NEW.family_id) BEGIN SELECT RAISE(ABORT,'CASE_MISMATCH'); END;
CREATE TRIGGER task_documents_case_update BEFORE UPDATE ON task_documents WHEN NOT EXISTS(SELECT 1 FROM documents d LEFT JOIN analysis_tasks a ON a.id=NEW.analysis_task_id LEFT JOIN execution_tasks e ON e.id=NEW.execution_task_id WHERE d.id=NEW.document_id AND (a.family_id=d.family_id OR e.family_id=d.family_id)) BEGIN SELECT RAISE(ABORT,'CASE_MISMATCH'); END;
CREATE TRIGGER meeting_items_case_update BEFORE UPDATE ON meeting_items WHEN NOT EXISTS(SELECT 1 FROM meetings m WHERE m.id=NEW.meeting_id AND m.family_id=NEW.family_id) BEGIN SELECT RAISE(ABORT,'CASE_MISMATCH'); END;
